   if(!nativeResponse||usedServerIds.has(nativeResponse.id)||nativeResponse.phase!==request.phase||origin+nativeResponse.path+nativeResponse.search!==request.url||nativeResponse.status!==200||nativeResponse.bytes!==local.length||nativeResponse.sha256!==localSha||!nativeResponse.finishedAt||request.responseStatus!==200){unclassified.push({observation,reason:'no unique completed exact native HTTP response receipt',request,nativeResponse});continue}
